<?php require_once __DIR__.'/includes/auth.php';$page_title='Payment Information';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete')db()->prepare('DELETE FROM payment_methods WHERE id=?')->execute([$id]);elseif($action==='toggle')db()->prepare('UPDATE payment_methods SET status=? WHERE id=?')->execute([($_POST['status']??'INACTIVE')==='ACTIVE'?'ACTIVE':'INACTIVE',$id]);elseif($action==='save'){ $data=[trim($_POST['name']??''),trim($_POST['account_name']??''),trim($_POST['account_number']??''),(int)($_POST['display_order']??1),($_POST['status']??'ACTIVE')==='ACTIVE'?'ACTIVE':'INACTIVE'];if(!$data[0]||!$data[1]||!$data[2]){flash('error','All fields are required.');go('payments.php');}if($id)db()->prepare('UPDATE payment_methods SET name=?,account_name=?,account_number=?,display_order=?,status=? WHERE id=?')->execute([...$data,$id]);else db()->prepare('INSERT INTO payment_methods(name,account_name,account_number,display_order,status,created_at) VALUES(?,?,?,?,?,NOW())')->execute($data);}log_activity('Payment method changed',(int)$admin['id']);flash('success','Payment information updated.');go('payments.php');}$edit=$id=0; if(!empty($_GET['edit'])){$id=(int)$_GET['edit'];$s=db()->prepare('SELECT * FROM payment_methods WHERE id=?');$s->execute([$id]);$edit=$s->fetch()?:0;}$rows=db()->query('SELECT * FROM payment_methods ORDER BY display_order,id')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Payment Information</h1><p>Only active methods are exposed by the public API.</p></div></div><div class="notice">Use placeholder/simulated account details only unless a verified provider and compliance process are configured.</div><section class="panel"><h2><?=is_array($edit)?'Edit':'Add'?> payment method</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=is_array($edit)?$edit['id']:0?>"><div class="form-grid"><div class="field"><label>METHOD</label><input class="input" name="name" value="<?=e(is_array($edit)?$edit['name']:'')?>" placeholder="ERAN+ Wallet" required></div><div class="field"><label>ACCOUNT NAME</label><input class="input" name="account_name" value="<?=e(is_array($edit)?$edit['account_name']:'')?>" placeholder="ERAN+ Account" required></div><div class="field"><label>ACCOUNT NUMBER</label><input class="input" name="account_number" value="<?=e(is_array($edit)?$edit['account_number']:'')?>" placeholder="123456789" required></div><div class="field"><label>DISPLAY ORDER</label><input class="input" type="number" name="display_order" value="<?=is_array($edit)?$edit['display_order']:1?>"></div><div class="field"><label>STATUS</label><select class="select" name="status"><option <?=is_array($edit)&&$edit['status']==='INACTIVE'?'':'selected'?>>ACTIVE</option><option <?=is_array($edit)&&$edit['status']==='INACTIVE'?'selected':''?>>INACTIVE</option></select></div></div><button class="button button-primary"><?=is_array($edit)?'UPDATE':'ADD'?> METHOD</button><?php if(is_array($edit)):?> <a class="button" href="payments.php">CANCEL</a><?php endif;?></form></section><section class="panel"><h2>Configured methods</h2><div class="table-wrap"><table class="table"><thead><tr><th>METHOD</th><th>ACCOUNT</th><th>NUMBER</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['account_name'])?></td><td><?=e($r['account_number'])?></td><td><span class="status <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><a class="button" href="payments.php?edit=<?=$r['id']?>">EDIT</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="<?=$r['status']==='ACTIVE'?'INACTIVE':'ACTIVE'?>"><button class="button <?= $r['status']==='ACTIVE'?'button-danger':'button-green' ?>"><?=$r['status']==='ACTIVE'?'DISABLE':'ENABLE'?></button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-danger" data-confirm="Delete this method?">DELETE</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
